let list: TodoList;
beforeEach(() => {
  list = new TodoList();
});

it('trims the text', () => expect(list.add('  Buy milk ').text).toBe('Buy milk'));
it('rejects empty text', () => expect(() => list.add('   ')).toThrow('required'));
it('completes the right task', () => {
  list.add('A');
  const b = list.add('B');
  list.complete(b.id);
  expect(list.items.map((t) => t.done)).toEqual([false, true]);
});
it('removes the right task', () => {
  const a = list.add('A');
  list.add('B');
  list.remove(a.id);
  expect(list.items.map((t) => t.text)).toEqual(['B']);
});
it('counts only active tasks', () => {
  const a = list.add('A');
  list.add('B');
  list.complete(a.id);
  expect(list.activeCount()).toBe(1);
});
```
